// ─── File: AdtDemo.java ───
// Single runnable file with multiple top-level package-private classes.
package com.bank.adt;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.logging.*;

public class AdtDemo {
    private static final Logger log = Logger.getLogger(AdtDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        OutcomeHandler handler = new OutcomeHandler();

        // Sum type: a PaymentOutcome is EXACTLY ONE of three record variants.
        List<PaymentOutcome> outcomes = List.of(
            new Success("TXF-1", new BigDecimal("50000")),
            new Failure("TXF-2", "Insufficient funds"),
            new Pending("TXF-3", LocalDate.of(2026, 10, 28)));

        for (PaymentOutcome o : outcomes) {
            log.info(() -> handler.message(o));
        }

        // Recursive ADT: fee formula = (1000 + 500) * 2 = 3000
        Expr formula = new Mul(new Add(new Literal(new BigDecimal("1000")),
                                        new Literal(new BigDecimal("500"))),
                               new Literal(new BigDecimal("2")));
        BigDecimal fee = Expr.eval(formula);
        log.info(() -> "Fee formula evaluates to Rs." + fee);
    }
}

// ─── Would be in outcome/PaymentOutcome.java ───
// SUM of PRODUCTS: sealed closes the variant set; each record bundles its fields.
// Illegal states are unrepresentable — Success has no reason, Failure has no amount.
sealed interface PaymentOutcome permits Success, Failure, Pending {
    String reference();
}
record Success(String reference, BigDecimal amount)     implements PaymentOutcome { }
record Failure(String reference, String reason)         implements PaymentOutcome { }
record Pending(String reference, LocalDate expectedDate) implements PaymentOutcome { }

// ─── Would be in service/OutcomeHandler.java ───
class OutcomeHandler {
    // Total function over the ADT: EXHAUSTIVE switch, record destructuring, no default.
    String message(PaymentOutcome o) {
        return switch (o) {
            case Success(String ref, BigDecimal amount) ->
                "SUCCESS " + ref + ": settled Rs." + amount;
            case Failure(String ref, String reason) ->
                "FAILURE " + ref + ": " + reason;
            case Pending(String ref, LocalDate date) ->
                "PENDING " + ref + ": expected " + date;
        };
    }
}

// ─── Would be in expr/Expr.java ───
// Recursive ADT: an Expr is a Literal, an Add of two Exprs, or a Mul of two Exprs.
sealed interface Expr permits Literal, Add, Mul {
    // Total evaluator over the closed set — the interpreter pattern, type-safely.
    static BigDecimal eval(Expr e) {
        return switch (e) {
            case Literal(BigDecimal v)        -> v;
            case Add(Expr left, Expr right)   -> eval(left).add(eval(right));
            case Mul(Expr left, Expr right)   -> eval(left).multiply(eval(right));
        };
    }
}
record Literal(BigDecimal value) implements Expr { }
record Add(Expr left, Expr right) implements Expr { }
record Mul(Expr left, Expr right) implements Expr { }

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override public String format(java.util.logging.LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
